import{_ as i,o as t,c as o,ag as r}from"./chunks/framework.DzGOF12C.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"후설","slug":"후설","link":"#후설","children":[]},{"level":2,"title":"하이데거","slug":"하이데거","link":"#하이데거","children":[{"level":3,"title":"염려","slug":"염려","link":"#염려","children":[]}]},{"level":2,"title":"사르트르","slug":"사르트르","link":"#사르트르","children":[]},{"level":2,"title":"메를로퐁티","slug":"메를로퐁티","link":"#메를로퐁티","children":[]}],"relativePath":"philosophy/Phenomenology/09. 기말고사 용어 정리.md","filePath":"philosophy/Phenomenology/09. 기말고사 용어 정리.md"}'),n={name:"philosophy/Phenomenology/09. 기말고사 용어 정리.md"};function s(e,l,a,g,p,u){return t(),o("div",null,[...l[0]||(l[0]=[r('<blockquote><p>기말고사 대비 전체 용어 압축 정리 (후설·하이데거·사르트르·메를로퐁티).</p></blockquote><h2 id="후설" tabindex="-1">후설 <a class="header-anchor" href="#후설" aria-label="Permalink to &quot;후설&quot;">​</a></h2><p><strong>마음</strong>: 주체와 그의 상태</p><p><strong>현상학적 심리학</strong>: 자연적 태도에서 세계와 몸을 전제한 채 마음을 탐구. 의식을 현상학적 반성을 통해 탐구.</p><ul><li>반성적 자기의식</li><li>선반성적 자기의식</li></ul><p><strong>일상적 마음인식</strong>: 자연적 태도로 마음인식 → <strong>몸</strong>과 함께 경험</p><ul><li><strong>고유감각 + 외부감각</strong></li><li><strong>관점</strong>의 주체 구성</li><li>국소화</li><li>세계, 행위</li><li><strong>동기부여</strong> — 마음의 인과 (배고프면 밥먹기 이런 것)</li><li>행위의 주체, 인격의 주체</li></ul><p><strong>현상학적 마음인식</strong></p><p><strong>타자를 어떻게 인식?</strong></p><ul><li>감정이입 — 비의도적, 암묵적으로 일어남</li><li>타자인식이 객관성의 근거 → 상호주관성</li></ul><h2 id="하이데거" tabindex="-1">하이데거 <a class="header-anchor" href="#하이데거" aria-label="Permalink to &quot;하이데거&quot;">​</a></h2><p><strong>현존재</strong>, <strong>실존</strong></p><p><strong>세계 내 존재</strong></p><ul><li>눈 앞에 있음</li><li>손 안에 있음 <ul><li>고려 — 손안에 있는 것과 관계</li><li>주위세계의 공간성 <ul><li>가까움: 손안에 있음</li><li>거리 없앰: 손 안에 넣을 수 있도록 함</li><li>방향잡음: 어떤 것을 손안에 넣을지 정함</li></ul></li></ul></li></ul><p><strong>안에 있는 자</strong></p><ul><li>함께 있음 — 손안에 있는 것을 함께 고려</li><li>배려 — 함께 있는 자에 대한 관계 방식</li><li>세인</li></ul><p><strong>안에 있음</strong> — 세계와 그 안에 살고 있는 존재자와의 관계</p><ul><li>처함, 기분</li><li>이해, 기획투사 → 가능성</li><li>말</li></ul><h3 id="염려" tabindex="-1">염려 <a class="header-anchor" href="#염려" aria-label="Permalink to &quot;염려&quot;">​</a></h3><p>자신을 앞서 / 이미 세계 안에 있으면서 / 어떤 존재자 곁에 있음</p><ul><li><strong>이해</strong>: (자신을 앞서)</li><li><strong>처함</strong>: (이미 세계 안에 있으면서)</li><li><strong>곁에 있음</strong>: (어떤 존재자 곁에 있음)</li></ul><p><strong>빠짐</strong></p><ul><li>애매성</li><li>호기심</li><li>잡담</li></ul><p><strong>결단</strong></p><ul><li>불안</li><li>탓</li><li>과묵함</li></ul><p><strong>현존재의 시간성</strong></p><ul><li>탈자태 — 자신의 모습에서 벗어남</li><li>장래 — 이해에서 나타나는 시간성</li><li>기재 — 처함에서 나타나는 시간성</li><li>현재 — 곁에 있음에서 나타나는 시간성</li></ul><p><strong>본래적 시간성</strong></p><ul><li>앞서달림 — 죽음으로 기획투사</li><li>회복 — 본래적 자신 회복</li><li>순간 — 고유한 의미를 가지는 존재자를 만남</li></ul><p><strong>비본래적 시간성</strong></p><ul><li>기대 — 특정한 존재자에 대한 가능성으로 기획투사</li><li>망각 — 고유한 자신을 잊음</li><li>현재화 — 그때그때 만나는 존재자를 만남</li></ul><h2 id="사르트르" tabindex="-1">사르트르 <a class="header-anchor" href="#사르트르" aria-label="Permalink to &quot;사르트르&quot;">​</a></h2><p>의식은 지향적임 → 감각자료는 대상에 속함</p><p><strong>선반성적 자기의식</strong></p><p><strong>즉자, 대자</strong></p><p><strong>무, 무화</strong></p><p><strong>의식의 본성</strong> — 무로 설명</p><ul><li>지향성 — 자신이 아닌 것으로 향함</li><li>욕구 — 자신이 없는 걸 추구</li><li>시간성 — 있는 것에서 없는 것으로 감</li></ul><p><strong>반성</strong> — 이로 나타나는 건 즉자</p><p><strong>타자</strong></p><ul><li>시선</li><li>투쟁</li></ul><p><strong>자유</strong></p><ul><li>불안 — 자유가 선반성적으로 자신을 의식</li><li>자기기만 — 대자가 불안을 피하는 방식</li></ul><h2 id="메를로퐁티" tabindex="-1">메를로퐁티 <a class="header-anchor" href="#메를로퐁티" aria-label="Permalink to &quot;메를로퐁티&quot;">​</a></h2><p>감각적 현상은 의식이 아니라 대상에 속함</p><p><strong>경험주의</strong>, <strong>지성주의</strong></p><ul><li>감각과 지각: 지각은 감각을 가지고 하는 게 아님. 지각 안에서만 감각.</li><li>객관적 세계에 괄호, 생활세계</li><li>자기-몸</li><li>환상지, 질병실인증 <ul><li>비정상적 감각의 산물이 아님 — 환자의 기억·감정·의지에 의존, 즉 절단 전 실천의 장을 가짐</li><li>잘못된 인식이 아님 — 암묵적으로 알고 경험</li></ul></li><li>세계에 있는 존재 — 암묵적으로 경험하는 몸</li><li>신체 도식 — 상황의 공간성</li><li>지향궁</li></ul>',47)])])}const d=i(n,[["render",s]]);export{_ as __pageData,d as default};
